<script setup lang="ts">const route=useRoute();const token=String(route.params.token);const{data,refresh}=await useFetch<any>(`/api/partner/ebike/${token}`);const busy=ref(false);async function act(a:'confirm'|'reject'){busy.value=true;await $fetch(`/api/partner/ebike/${token}/${a}`,{method:'POST'});await refresh();busy.value=false}</script>
<template><main class="min-h-screen bg-stone-50 p-6"><div v-if="data" class="mx-auto max-w-lg space-y-5 rounded-xl bg-white p-6 shadow"><h1 class="text-xl font-semibold">Povpraševanje za e-kolesa</h1><dl class="space-y-2 text-sm"><div><b>Gost:</b> {{data.guestName}}</div><div><b>Obdobje:</b> {{data.startDate}}–{{data.endDate}}</div><div><b>Število:</b> {{data.bikeCount}}</div><div><b>Znesek:</b> {{data.totalPrice.toFixed(2)}} EUR</div><div><b>Opombe:</b> {{data.notes||'—'}}</div></dl><div v-if="data.actionable" class="flex gap-3"><button :disabled="busy" class="flex-1 rounded-lg bg-pine-600 p-3 text-white" @click="act('confirm')">Potrdi</button><button :disabled="busy" class="flex-1 rounded-lg bg-maple-600 p-3 text-white" @click="act('reject')">Zavrni</button></div><p v-else>Status: {{data.status}}</p></div></main></template>
